#!/usr/bin/env bash
# Compiles the Java generated by src/lib/java.ts with a real javac (plain, Lombok and record modes)
# and round-trips each sample JSON through Jackson (deserialize -> serialize -> compare trees).
# Requires: JDK 17+ (javac/java), curl, node. Jars are downloaded from Maven Central into $JAR_DIR.
set -euo pipefail
cd "$(dirname "$0")/.."
JAR_DIR="${JAR_DIR:-/tmp/json-world-jars}"
OUT="${OUT:-/tmp/json-world-java}"
JACKSON="${JACKSON_VERSION:-2.18.2}"
LOMBOK="${LOMBOK_VERSION:-1.18.36}"
mkdir -p "$JAR_DIR"
fetch() { [ -s "$JAR_DIR/$2" ] || curl -sfL -o "$JAR_DIR/$2" "https://repo1.maven.org/maven2/$1/$2"; }
fetch com/fasterxml/jackson/core/jackson-annotations/$JACKSON jackson-annotations-$JACKSON.jar
fetch com/fasterxml/jackson/core/jackson-core/$JACKSON jackson-core-$JACKSON.jar
fetch com/fasterxml/jackson/core/jackson-databind/$JACKSON jackson-databind-$JACKSON.jar
fetch org/projectlombok/lombok/$LOMBOK lombok-$LOMBOK.jar
CP="$JAR_DIR/jackson-annotations-$JACKSON.jar:$JAR_DIR/jackson-core-$JACKSON.jar:$JAR_DIR/jackson-databind-$JACKSON.jar"
rm -rf "$OUT" && mkdir -p "$OUT/classes"
npx vite-node scripts/java-verify/gen.ts "$OUT"
javac -version
find "$OUT/src" -name '*.java' > "$OUT/sources.txt"
echo "compiling $(wc -l < "$OUT/sources.txt") generated files (+ Verify.java)…"
javac -Xlint:none -nowarn -d "$OUT/classes" -cp "$CP:$JAR_DIR/lombok-$LOMBOK.jar" -processorpath "$JAR_DIR/lombok-$LOMBOK.jar" \
  @"$OUT/sources.txt" scripts/java-verify/Verify.java
java -cp "$OUT/classes:$CP" Verify "$OUT/cases.txt"
